SELECT id, store_id, order_date, channel, amount, shipping_fee, COUNT(shipping_fee) OVER w_recent AS channel_count_shipping_fee, NTILE(3) OVER w_hist AS discount_bucket, CUME_DIST() OVER (ORDER BY amount DESC NULLS FIRST) AS amount_cume_dist, FIRST_VALUE(shipping_fee) IGNORE NULLS OVER (ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_shipping_fee FROM orders WINDOW w_recent AS (PARTITION BY channel, store_id), w_hist AS (PARTITION BY channel ORDER BY discount, id);
